<script lang="ts">
import {copy as ui,plural,practiceCount,minutes,sourceLabel,collectionColor} from './config/copy';

 import {dailyPlan,estimateMinutes} from './daily';
 import {onMount} from 'svelte';
 import ProgressPie from './components/ProgressPie.svelte';
 import {RULES} from './config/rules';
 import {startRegistration,startAuthentication} from '@simplewebauthn/browser';
 import Button from './components/Button.svelte';import List from './components/List.svelte';import Row from './components/Row.svelte';import Cover from './components/Cover.svelte';import Sheet from './components/Sheet.svelte';import StepDots from './components/StepDots.svelte';import WeekDots from './components/WeekDots.svelte';import TabBar from './components/TabBar.svelte';import Keyboard from './components/Keyboard.svelte';import VerseText from './components/VerseText.svelte';
 import {tokenize,firstLetters,maskWords,grade,transition,schedule,gentleCap} from './engine';
 import {starters,documents,lookupReference} from './content';
 import {openStore,persist,api,mergeItems,mergeSettings,stampSettings,clearStore,installReconnectSync,sortItems,addItems,defaults,today,type LocalState,type Item} from './store';
 let data=$state<LocalState>({items:[],events:[],settings:{...defaults},queue:[]});
 let ready=$state(false),tab=$state<string>(location.pathname===ui.galleryPath&&(import.meta.env.DEV||localStorage.debug==='1')?ui.gallery:ui.today),detail=$state<string>(ui.empty),practice=$state<Item|null>(null),session=$state<string[]>([]),position=$state(0),slips=$state<number[]>([]),result=$state(false),learned=$state(false),shortcut=$state(false),review=$state(false),message=$state<string>(ui.empty),error=$state<string>(ui.empty),busy=$state(false),account=$state<any>(null),config=$state<any>({}),recovery=$state<string>(ui.empty),recoverInput=$state<string>(ui.empty),confirmDelete=$state(false),welcome=$state(false),addMode=$state<string>(ui.verseMode),reference=$state<string>(ui.empty),translation=$state<string>(ui.bsb),customTitle=$state<string>(ui.empty),customText=$state<string>(ui.empty),found=$state<any[]>([]),selectedDoc=$state<string>(ui.empty),nextDue=$state<string>(ui.empty);
 let visualSlips=$state<number[]>([]),rehearsal=$state(false),resultTitle=$state(''),resultDetail=$state(''),resultLearned=$state(false);
 let online=$state(navigator.onLine);
 let preview=$state<any>(null),removeTarget=$state<Item|null>(null),undoItem=$state<Item|null>(null),separate=$state(false),splitLong=$state(false),confirmBatch=$state<any[]|null>(null),batchCollection=$state<string|undefined>(),confirmSignout=$state(false),mergePrompt=$state(false),discardPrompt=$state(false),zoneSearch=$state('');
 const zones=[...new Set(['UTC',...Intl.supportedValuesOf('timeZone')])];
 const attemptStep=$derived(review||shortcut||rehearsal?4:practice?.step||1);
 const live=$derived(sortItems(data.items.filter(i=>!i.deleted)));
 const calendarDays=(date:string)=>Math.max(0,Math.round((Date.parse(today())-Date.parse(date))/86400000)||0);
 const daysAway=$derived(data.settings.lastActive?calendarDays(data.settings.lastActive):0);
 const rampDay=$derived(data.settings.returnStart?calendarDays(data.settings.returnStart):7);
 const cap=$derived(gentleCap(data.settings.returnStart&&rampDay<7?7:daysAway,rampDay,RULES.daily.normalCap));
 const newLimit=$derived(Number((data.settings as any).newPerDay)||3);
 const due=$derived(dailyPlan(live,data.events,today(),newLimit,Date.now(),daysAway>=7||data.settings.returnStart&&rampDay<7?cap:Infinity));
 const estimatedMinutes=$derived(estimateMinutes(due));
 const words=$derived(practice?tokenize(practice.text):[]);
 const mask=$derived(practice?maskWords(practice.text,attemptStep):[]);
 const hidden=$derived(mask.filter(Boolean).length);
 const detailItems=$derived(live.filter(i=>i.collection===detail));
 const weekCount=$derived(data.settings.days.filter(d=>{const date=new Date(d+ui.middaySuffix);const now=new Date();now.setDate(now.getDate()-((now.getDay()+6)%7));now.setHours(0,0,0,0);return date>=now}).length);
 function theme(){document.documentElement.dataset.theme=data.settings.theme}
 async function save(){data.settings=stampSettings($state.snapshot(data.settings),savedSettings);savedSettings=structuredClone($state.snapshot(data.settings));data.account=account;data.settings=await persist($state.snapshot(data));savedSettings=structuredClone($state.snapshot(data.settings));theme();if(account&&!mergePrompt)void sync()}
 let savedSettings=structuredClone(defaults);
 let syncing=false,syncAgain=false;
 let addTarget=$state<string>(ui.empty);
 async function sync(){const userAtStart=account;if(!userAtStart||mergePrompt)return;if(syncing){syncAgain=true;return}syncing=true;try{const items=$state.snapshot(data.items),events=$state.snapshot(data.events);let out:any;const batches=Math.max(1,Math.ceil(items.length/500),Math.ceil(events.length/1000));for(let n=0;n<batches;n++)out=await api(ui.syncPath,{items:items.slice(n*500,(n+1)*500),events:events.slice(n*1000,(n+1)*1000),settings:$state.snapshot(data.settings)});
 if(account?.id!==userAtStart.id)return;data.items=mergeItems(data.items,out.items||[]);if(out.settings)data.settings=mergeSettings(data.settings,out.settings);savedSettings=structuredClone($state.snapshot(data.settings));theme();const map=new Map(data.events.map(e=>[e.id,e]));for(const e of out.events||[])map.set(e.id,e);data.events=[...map.values()];data.queue=[];online=true;await persist($state.snapshot(data));if(!message||message===ui.allSaved||message===ui.savedOffline)message=ui.allSaved}catch(e){online=false;message=ui.savedOffline}finally{syncing=false;if(syncAgain){syncAgain=false;if(account&&!mergePrompt)void sync()}}}

 async function attempt(fn:()=>Promise<void>){busy=true;error=ui.empty;message=ui.empty;try{await fn()}catch(e){error=e instanceof DOMException&&['NotAllowedError','AbortError'].includes(e.name)?ui.passkeyCanceled:e instanceof Error?e.message:String(e)}finally{busy=false}}
 onMount(()=>{history.replaceState({byheart:true,rootGuard:true,tab,detail:''},'');history.pushState({byheart:true,tab,detail:''},'');const back=(event:PopStateEvent)=>{if(suppressPop){suppressPop=false;return}if(discardPrompt){discardPrompt=false}else if(mergePrompt){history.pushState({byheart:true,tab,detail,sheet:true},'')}else if(result){result=false;practice=null}else if(welcome){welcome=false}else if(confirmSignout){confirmSignout=false}else if(preview){preview=null}else if(removeTarget){removeTarget=null}else if(confirmBatch){confirmBatch=null}else if(confirmDelete){confirmDelete=false}else if(recovery){recovery=''}else if(practice){practice=null;learned=false;result=false}else{tab=event.state?.tab||ui.today;detail=event.state?.detail||''}window.scrollTo(0,0);if(!event.state?.byheart||event.state?.rootGuard)history.pushState({byheart:true,tab,detail},'')};window.addEventListener('popstate',back);
 void attempt(async()=>{data=await openStore();data.settings={...defaults,newPerDay:3,...data.settings};savedSettings=structuredClone($state.snapshot(data.settings));account=data.account||null;mergePrompt=!!(data as any).pendingMerge;ready=true;theme();welcome=daysAway>=7&&rampDay>=7&&live.some(i=>i.learned);void api('/config').then(out=>config=out).catch(()=>{});try{const out=await api('/me');if(out.recoveryCode)recovery=out.recoveryCode;await refreshIdentity(out.user||out.account||null)}catch{online=false}});
 const connection=()=>online=navigator.onLine;window.addEventListener('online',connection);window.addEventListener('offline',connection);
 const retry=installReconnectSync(async()=>{try{const out=await api('/me');if(out.user)await refreshIdentity(out.user)}catch{}});return()=>{retry();window.removeEventListener('online',connection);window.removeEventListener('offline',connection);window.removeEventListener('popstate',back)}});
 let modalOpen=false,suppressPop=false;
 $effect(()=>{const opened=!!(preview||removeTarget||confirmBatch||confirmDelete||recovery||welcome||confirmSignout||mergePrompt||discardPrompt||result);if(opened&&!modalOpen)history.pushState({byheart:true,tab,detail,sheet:true},'');else if(!opened&&modalOpen&&history.state?.sheet){suppressPop=true;history.back()}modalOpen=opened});
 function pushView(){history.pushState({byheart:true,tab,detail,practice:!!practice},'');window.scrollTo(0,0)}
 function navigate(to:string){addTarget='';tab=to;detail='';error='';message='';pushView()}
 function openCollection(id:string){addTarget='';tab=ui.library;detail=id;pushView()}
 const collectionTitle=(id:string)=>starters.find(s=>s.id===id)?.title||documents.find(d=>d.id===id)?.title||({bible:ui.myVerses,personal:ui.myTexts}[id])||ui.myTexts;
 async function add(items:any[],collectionId?:string,confirmed=false){if(items.length>20&&!confirmed){confirmBatch=items;batchCollection=collectionId;return}const count=items.filter(item=>!live.some(i=>i.id===item.id)).length;data.items=addItems(data.items,items,addTarget||collectionId);if(count){data.queue.push(crypto.randomUUID());await save()}message=count?ui.itemsAdded(count):ui.alreadyAdded}
 async function addStarter(s:any){addTarget='';await add(s.items,s.id);preview=null;openCollection(s.id)}
 function begin(items:Item[]){if(!items.length)return;session=items.map(i=>i.id);loadNext();pushView()}
 function loadNext(){const id=session.shift();if(!id){practice=null;learned=false;result=false;return}const item=live.find(i=>i.id===id);if(!item){loadNext();return}practice={...item};review=item.learned;shortcut=false;rehearsal=false;learned=false;position=0;slips=[];visualSlips=[];result=false;nextDue=''}
 function key(key:string,peek=false){if(!practice||result||learned||position>=words.length)return;const wrong=peek||!firstLetters(words[position]).includes(key.toLowerCase());if(wrong){visualSlips.push(position);if(mask[position])slips.push(position)}position++;if(position>=words.length){result=true;void finish()}}
 function physical(e:KeyboardEvent){if(practice&&!result&&!learned&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&/^[a-z0-9]$/i.test(e.key)){e.preventDefault();key(e.key)}}
 async function finish(){if(!practice)return;const now=new Date(),step=attemptStep,wasReview=review,hiddenCount=hidden;const g=grade(slips.length,hiddenCount);const out=transition(step,slips.length,hiddenCount,shortcut);resultLearned=false;resultTitle=wasReview?({Again:ui.reviewAgain,Hard:ui.reviewHard,Good:ui.reviewGood,Easy:ui.reviewEasy}[g]):out.learned?ui.learned:out.step>step?ui.stepPassedTitle(step):ui.repeatStep;resultDetail=step===1?ui.readAlongDone:ui.memoryResult(hiddenCount,slips.length);if(rehearsal){resultTitle=ui.practiceComplete;return}let fsrsLog:any=null;
 if(wasReview||out.learned){const scheduled=schedule(practice.card,g,now);fsrsLog=scheduled.log;practice.card=scheduled.card;practice.due=new Date(scheduled.card.due).toISOString();nextDue=new Date(practice.due).toLocaleDateString(undefined,{weekday:'long'});resultDetail=ui.backOn(nextDue);if(wasReview){practice.learned=g!=='Again';practice.step=g==='Again'?3:4}else{practice.step=out.step;practice.learned=true;practice.learnedAt=now.toISOString()}resultLearned=practice.learned}else{practice.step=out.step;practice.learned=out.learned}
 practice.updatedAt=Date.now();const index=data.items.findIndex(i=>i.id===practice!.id&&!i.deleted);if(index>=0)data.items[index]={...practice};const event={id:crypto.randomUUID(),itemId:practice.id,at:now.toISOString(),slips:slips.length,hidden:hiddenCount,grade:g,mode:wasReview?'review':'learn',step,fsrsLog};data.events.push(event);data.queue.push(event.id);if(!data.settings.days.includes(today()))data.settings.days.push(today());data.settings.lastActive=today();await save()}
 function continueResult(){result=false;if(rehearsal){practice=null;return}learned=resultLearned;if(!learned)review=practice?.learned||false;shortcut=false;position=0;slips=[];visualSlips=[]}
 async function refreshIdentity(user:any){const previous=account?.id;account=user;data.account=user;if(user&&previous!==user.id&&(data.items.length||data.events.length)){await afterSignin();return}await persist($state.snapshot(data));if(user)await sync()}
 async function afterSignin(){data.account=account;if(data.items.length||data.events.length){mergePrompt=true;(data as any).pendingMerge=true;await persist($state.snapshot(data));return}await persist($state.snapshot(data));await sync()}
 async function acceptMerge(){mergePrompt=false;(data as any).pendingMerge=false;await sync()}
 async function discardLocal(){discardPrompt=false;mergePrompt=false;(data as any).pendingMerge=false;data.items=[];data.events=[];data.queue=[];await save();await sync()}
 async function signup(){await attempt(async()=>{const options=await api(ui.registerOptionsPath,{displayName:data.settings.name});const response=await startRegistration({optionsJSON:options.options||options});const out=await api(ui.registerVerifyPath,{response,name:data.settings.name});account=out.user||out.account;recovery=out.recoveryCode||ui.empty;await afterSignin()})}
 async function signin(){await attempt(async()=>{const options=await api(ui.loginOptionsPath,{});const response=await startAuthentication({optionsJSON:options.options||options});const out=await api(ui.loginVerifyPath,{response});account=out.user||out.account;await afterSignin()})}
 async function recover(){await attempt(async()=>{const out=await api(ui.recoverPath,{code:recoverInput});account=out.user||out.account;recovery=out.recoveryCode||ui.empty;recoverInput=ui.empty;await afterSignin()})}
 async function signout(){await attempt(async()=>{await sync();if(data.queue.length)throw Error(ui.signoutNeedsConnection);await api('/auth/logout',{});account=null;data=await clearStore();savedSettings=structuredClone(defaults);message=ui.signedOutCleared})}
 async function exportData(){await attempt(async()=>{const out=account?await api(ui.exportPath):$state.snapshot(data);const a=document.createElement(ui.anchorTag);a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:ui.jsonMime}));a.download=ui.exportFilename;a.click();URL.revokeObjectURL(a.href);message=ui.exportReady})}
 async function deleteAccount(){await attempt(async()=>{await api(ui.accountPath,undefined,ui.deleteMethod);account=null;confirmDelete=false;message=ui.accountDeleted})}
 async function enablePush(){await attempt(async()=>{if(!account)throw Error(ui.signInForReminders);if(!(ui.notificationApi in window)||!(ui.pushManagerApi in window))throw Error(ui.iosInstallNotice);const permission=await Notification.requestPermission();if(permission!==ui.permissionGranted)throw Error(ui.notificationDenied);const reg=await navigator.serviceWorker.ready;const raw=config.vapidPublicKey||config.vapid; if(!raw)throw Error(ui.vapidUnavailable);const key=Uint8Array.from(atob(raw.replace(/-/g,ui.base64Plus).replace(/_/g,ui.base64Slash)),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api(ui.pushSubscribePath,{subscription:sub.toJSON()});data.settings.pushEnabled=true;await save();message=ui.remindersEnabled})}
 async function disablePush(){await attempt(async()=>{const reg=await navigator.serviceWorker.ready;await (await reg.pushManager.getSubscription())?.unsubscribe();await api(ui.pushSubscribePath,{subscription:null});data.settings.pushEnabled=false;await save()})}
 async function search(){await attempt(async()=>{found=await lookupReference(reference,translation);if(!found.length)throw Error(ui.noVersesFound)})}
 async function own(){await attempt(async()=>{if(!customTitle.trim()||!customText.trim())throw Error(ui.missingCustomText);await add([{id:crypto.randomUUID(),title:customTitle.trim(),text:customText.trim(),collection:ui.personalCollection}]);customTitle=ui.empty;customText=ui.empty;openCollection(addTarget||'personal')})}
 function know(){if(practice){shortcut=true;position=0;slips=[];visualSlips=[]}}
 function restart(){position=0;slips=[];visualSlips=[];result=false}
 async function remove(item:Item){item.deleted=true;item.updatedAt=Date.now();removeTarget=null;undoItem=item;await save();setTimeout(()=>{if(undoItem?.id===item.id)undoItem=null},5000)}
 async function undo(){if(!undoItem)return;undoItem.deleted=false;undoItem.updatedAt=Date.now();undoItem=null;await save()}
 function passageItems(){if(separate||found.length<2)return found;const groups=splitLong?Array.from({length:Math.ceil(found.length/4)},(_,i)=>found.slice(i*4,i*4+4)):[found];return groups.map(group=>({...group[0],id:group[0].id+'--'+group.at(-1).id,title:group[0].title+'–'+group.at(-1).title.split(' ').at(-1),text:group.map(i=>i.text).join(' ')}))}

</script>
<svelte:window onkeydown={physical}/>
<main class:practicing={!!practice&&!learned}>
{#if !ready}<section class="empty"><h1>{ui.appName}</h1><p>{ui.loadingBody}</p></section>
{:else if practice}
 {#if learned}<section class="learned"><svg class="learned-check" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 25l9 9L39 14"/></svg><h1>{review?ui.reviewed:ui.learned}</h1><article class="keepsake" style:background={collectionColor(practice)}><p>{practice.text}</p><footer><b>{practice.title}</b><small>{sourceLabel(practice)}</small></footer></article>{#if nextDue}<small>{ui.nextReviewPrefix}{nextDue}</small>{/if}<Button onclick={loadNext}>{session.length?ui.nextItem:ui.backToToday}</Button><Button secondary onclick={()=>{learned=false;rehearsal=true;review=false;restart()}}>{ui.practiceOnceMore}</Button></section>
 {:else}<section class="practice" inert={result} aria-hidden={result}><header><button class="icon" aria-label={ui.closePractice} onclick={()=>practice=null}>×</button><StepDots step={attemptStep}/>{#if attemptStep===1&&!review}<Button secondary onclick={know}>{ui.knowThis}</Button>{:else}<button class="icon" aria-label={ui.restartStep} onclick={restart}>↻</button>{/if}</header><div class="prompt"><small>{review?ui.reviewBlankRecall:ui.stepPrefix+attemptStep+ui.stepOfFour+[ui.empty,ui.readAlong,ui.fewWordsHidden,ui.almostFromMemory,ui.fromMemory][attemptStep]}</small><h1>{practice.title}</h1><small>{sourceLabel(practice)}</small></div><div class="progress"><i style:width={position/words.length*100+ui.percent}></i></div><VerseText {words} {mask} text={practice.text} index={position} slipped={visualSlips}/><Keyboard onkey={key} onpeek={()=>key(ui.empty,true)} disabled={result}/></section>{/if}
 {#if result}<Sheet title={resultTitle}><p>{resultDetail}</p><Button onclick={continueResult}>{rehearsal?ui.done:resultLearned?ui.finish:ui.continue}</Button><Button secondary onclick={()=>{practice=null;result=false}}>{ui.closePractice}</Button></Sheet>{/if}
{:else}
 <section class="page" class:account={tab===ui.account}>
 <header><div><h1>{detail?collectionTitle(detail):tab===ui.account?ui.accountTitle:tab===ui.gallery?ui.components:tab}</h1>{#if tab===ui.today}<p>{new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"})}</p>{/if}</div><button class="icon" aria-label={detail?ui.backToLibrary:ui.accountSettings} onclick={()=>detail?openCollection(''):navigate(ui.account)}>{#if detail}{ui.backGlyph}{:else if data.settings.name.trim()}{data.settings.name.trim().slice(0,1).toUpperCase()}{:else}<svg class="person" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>{/if}</button></header>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if tab===ui.today}
 <div class="rhythm"><div><b>{weekCount}{ui.of}{data.settings.goal}{ui.thisWeekSuffix}</b></div><WeekDots days={data.settings.days}/></div>
 {#if due.length}<div class="hero"><div><b>{practiceCount(due.length)}</b><small>{minutes(estimatedMinutes)}</small></div><Button onclick={()=>begin(due)}>{ui.begin}</Button></div><h3 class="section-title">{ui.forToday}</h3><List>{#each due as item}<Row title={item.title} subtitle={`${item.learned?ui.review:item.step===1?ui.new:ui.learningStep(item.step)} · ${sourceLabel(item)}`} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row>{/each}</List>
 {:else}<div class="empty"><div class="heart">♡</div><h2>{live.length?ui.doneForToday:ui.noItemsYet}</h2>{#if !live.length}<p>{ui.addCollection}</p>{/if}<Button onclick={()=>navigate(ui.library)}>{live.length?ui.visitLibrary:ui.browseLibrary}</Button></div>{/if}
 {:else if tab===ui.library}
 {#if detail}<Cover title={collectionTitle(detail)} subtitle={plural(detailItems.length,"item")} color={starters.findIndex((s:any)=>s.id===detail)} large/><div class="section-title"><h3>{ui.yourItems}</h3><button class="text-button" onclick={()=>{const target=detail;navigate(ui.discover);addTarget=target}}>{ui.addItems}</button></div><List>{#each detailItems as item}<Row title={item.title} subtitle={item.learned?ui.reviewDate(item.due):ui.stepPrefix+item.step} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row><button class="text-button item-menu" aria-label={ui.optionsPrefix+item.title} onclick={()=>removeTarget=item}>…</button>{#if !item.learned&&!due.some(i=>i.id===item.id)}<button class="text-button" onclick={()=>begin([item])}>{ui.startEarly}</button>{/if}{/each}</List>{#if detailItems.length}<Button onclick={()=>begin(detailItems)}>{ui.startPractice}</Button>{:else}<p>{ui.nothingHere}</p>{/if}
 {:else}<h3 class="section-title">{ui.startHere}</h3><div class="covers">{#each starters as s,i}<Cover title={s.title} subtitle={(live.some(item=>item.collection===s.id)?ui.learnedCheck:'')+s.subtitle} color={i} onclick={()=>live.some(item=>item.collection===s.id)?openCollection(s.id):preview=s}/>{/each}</div><div class="section-title"><h3>{ui.yours}</h3><button class="text-button" onclick={()=>navigate(ui.discover)}>{ui.addShortcut}</button></div><List>{#each [...new Set(live.map(i=>i.collection))] as id}{@const items=live.filter(i=>i.collection===id)}<Row title={collectionTitle(id)} subtitle={items.filter(i=>i.learned).length+ui.of+items.length+ui.learnedSuffix} onclick={()=>openCollection(id)}><ProgressPie percent={items.filter(i=>i.learned).length/items.length*100}/></Row>{/each}</List>{#if !live.length}<p>{ui.libraryEmpty}</p>{/if}{/if}
 {:else if tab===ui.discover}
 <div class="stack"><div class="segments" aria-label={ui.contentType}>{#each [[ui.verseMode,ui.verses],[ui.ownMode,ui.yourText],[ui.documentsMode,ui.catechisms]] as [id,label]}<button class="segment" class:active={addMode===id} aria-pressed={addMode===id} onclick={()=>{addMode=id;found=[]}}>{label}</button>{/each}</div>
 {#if addMode===ui.verseMode}<label>{ui.translation}<select bind:value={translation}><option>{ui.bsb}</option><option>{ui.kjv}</option><option>{ui.web}</option></select></label><label>{ui.bibleReference}<input bind:value={reference} placeholder={ui.referencePlaceholder} onkeydown={e=>{if(e.key===ui.enterKey)void search()}}/></label><Button onclick={()=>void search()} disabled={busy}>{ui.findVerses}</Button>{#if found.length}<List>{#each found as item}<Row title={item.title} subtitle={item.text}/>{/each}</List><label class="toggle"><input type="checkbox" bind:checked={separate}/>{ui.addSeparate}</label>{#if tokenize(found.map(i=>i.text).join(' ')).length>150}<label class="toggle"><input type="checkbox" bind:checked={splitLong}/>{ui.splitSuggestion}</label>{/if}<Button onclick={()=>void add(passageItems())}>{ui.addToLibrary}</Button>{/if}<small>{ui.publicDomainNotice}</small>
 {:else if addMode===ui.ownMode}<label>{ui.titleOrQuestion}<input bind:value={customTitle} maxlength={200}/></label><label>{ui.textToRemember}<textarea bind:value={customText} maxlength={10000}></textarea></label><p>{ui.privateTextNotice}</p><Button onclick={()=>void own()}>{ui.addYourText}</Button>
 {:else}<label>{ui.browse}<select bind:value={selectedDoc}><option value="">{ui.chooseDocument}</option>{#each documents as doc}<option value={doc.id}>{doc.title}</option>{/each}</select></label>{#if selectedDoc}{@const doc=documents.find((d:any)=>d.id===selectedDoc)}{#if doc}<div class="bulk-actions"><Button secondary onclick={()=>void add(doc.items.slice(0,12),doc.id)}>{ui.addFirstQuestions}</Button><Button secondary onclick={()=>void add(doc.items.filter(i=>!live.some(x=>x.id===i.id)).slice(0,12),doc.id)}>{ui.addNextQuestions}</Button><Button secondary onclick={()=>{confirmBatch=doc.items;batchCollection=doc.id}}>{ui.addAll}</Button></div><List>{#each doc.items as item,i}{#if item.lordsDay&&(i===0||doc.items[i-1].lordsDay!==item.lordsDay)}<h3>{ui.lordsDay(item.lordsDay)}</h3>{/if}<details><summary>{item.number?ui.questionPrefix(item.number):''}{item.title}</summary><p>{item.text}</p></details><button class="text-button" onclick={()=>void add([item],doc.id)}>{live.some(x=>x.id===item.id)?ui.added:item.number?ui.addQuestion(item.number):ui.addArticle}</button>{/each}</List>{/if}{/if}{/if}</div>
 {:else if tab===ui.account}
 <div class="stack"><section class="settings-group" aria-label={ui.preferences}><label>{ui.displayName}<input bind:value={data.settings.name} onchange={()=>void save()} maxlength={80}/></label><label>{ui.appearance}<select bind:value={data.settings.theme} onchange={()=>void save()}><option value="system">{ui.system}</option><option value="light">{ui.light}</option><option value="dark">{ui.dark}</option></select></label><label>{ui.weeklyRhythm}<select bind:value={data.settings.goal} onchange={()=>void save()}>{#each RULES.rhythmOptions as n}<option value={n}>{ui.weekOption(n)}</option>{/each}</select></label><label>{ui.reminderTime}<input type="time" bind:value={data.settings.reminderTime} onchange={()=>void save()}/></label><label>{ui.newPerDay}<select bind:value={(data.settings as any).newPerDay} onchange={()=>void save()}>{#each [1,2,3,5] as n}<option value={n}>{n}</option>{/each}</select></label><label>{ui.searchZones}<input type="search" placeholder={ui.searchZones} bind:value={zoneSearch}/></label><label>{ui.timeZone}<select bind:value={data.settings.timeZone} onchange={()=>void save()}>{#each zones.filter(z=>z===data.settings.timeZone||z.toLowerCase().includes(zoneSearch.toLowerCase())) as zone}<option>{zone}</option>{/each}</select></label>
 </section><section class="settings-group" aria-labelledby="account-heading"><h3 id="account-heading">{ui.yourAccount}</h3>{#if account}<p>{ui.signedIn}</p>{#if !online}<small>{ui.offlineSync}</small>{/if}<Button secondary onclick={()=>confirmSignout=true}>{ui.signOut}</Button><Button secondary onclick={()=>void attempt(async()=>{await api('/auth/logout-everywhere',{});account=null;data=await clearStore();savedSettings=structuredClone(defaults)})}>{ui.signoutEverywhere}</Button>{:else}<p>{ui.localAccountNotice}</p><Button onclick={()=>void signup()} disabled={busy}>{ui.createPasskey}</Button><Button secondary onclick={()=>void signin()} disabled={busy}>{ui.signInPasskey}</Button>{#if config.google}<Button secondary onclick={()=>location.href=ui.googleAuthPath}>{ui.continueGoogle}</Button>{/if}<label>{ui.recoveryCode}<input bind:value={recoverInput} autocomplete="off"/></label><Button secondary onclick={()=>void recover()} disabled={busy||!recoverInput}>{ui.useRecoveryCode}</Button>{/if}
 </section><section class="settings-group" aria-labelledby="reminder-heading"><h3 id="reminder-heading">{ui.reminders}</h3><p>{ui.reminderInstructions}</p><Button secondary onclick={()=>void (data.settings.pushEnabled?disablePush():enablePush())}>{data.settings.pushEnabled?ui.disableReminders:ui.enableReminders}</Button>{#if data.settings.pushEnabled}<Button secondary onclick={()=>void attempt(async()=>{await api(ui.testPushPath,{});message=ui.testPushSent})}>{ui.sendTestPush}</Button>{/if}
 </section><section class="settings-group" aria-label={ui.dataLabel}><Button secondary onclick={()=>void exportData()}>{ui.exportData}</Button>{#if account}<Button secondary onclick={()=>confirmDelete=true}>{ui.deleteAccount}</Button>{/if}</section><small>{ui.aboutApp}</small></div>
 {:else if tab===ui.gallery}<div class="gallery"><Button>{ui.primaryButton}</Button><Button secondary>{ui.secondaryButton}</Button><StepDots step={3}/><WeekDots days={data.settings.days}/><Cover title={ui.gospelTitle} subtitle={ui.galleryVerseCount} color={0} large/><Row title={ui.johnReference} subtitle={ui.galleryStep}><StepDots step={2}/></Row><VerseText words={[ui.sampleFor,ui.sampleGod,ui.sampleSo,ui.sampleLoved,ui.sampleThe,ui.sampleWorld]} mask={[false,true,false,true,true,false]} index={2}/><Keyboard onkey={()=>{}} onpeek={()=>{}}/></div>{/if}
 </section><TabBar active={tab} onchange={navigate}/>
{/if}
{#if recovery}<Sheet title={ui.recoveryTitle}><p>{ui.recoveryInstructions}</p><code data-testid="recovery-code">{recovery}</code><Button onclick={()=>recovery=ui.empty}>{ui.recoverySaved}</Button></Sheet>{/if}
{#if confirmDelete}<Sheet title={ui.deleteTitle} close={()=>confirmDelete=false}><p>{ui.deleteInstructions}</p><Button onclick={()=>void deleteAccount()}>{ui.confirmDelete}</Button><Button secondary onclick={()=>confirmDelete=false}>{ui.keepAccount}</Button></Sheet>{/if}
{#if welcome}<Sheet title={ui.welcomeBack}><p>{ui.welcomeCount(Math.min(3,live.filter(i=>i.learned).length))}</p><Button onclick={()=>{data.settings.returnStart=today();welcome=false;void save()}}>{ui.start}</Button><Button secondary onclick={()=>{data.settings.returnStart=today();welcome=false;void save();begin(live.filter(i=>i.learned).slice(0,3))}}>{ui.checkMemory}</Button></Sheet>{/if}
{#if preview}<Sheet title={preview.title} close={()=>preview=null}><List>{#each preview.items as item}<Row title={item.title} subtitle={item.text}/>{/each}</List><Button onclick={()=>void addStarter(preview)}>{ui.addToMyLibrary}</Button></Sheet>{/if}
{#if removeTarget}<Sheet title={ui.removeTitle} close={()=>removeTarget=null}><p>{ui.removeDetail(removeTarget.title)}</p><Button onclick={()=>void remove(removeTarget!)}>{ui.remove}</Button><Button secondary onclick={()=>removeTarget=null}>{ui.keepItem}</Button></Sheet>{/if}
{#if undoItem}<div class="undo-toast" role="status">{ui.removed} <button class="text-button" onclick={()=>void undo()}>{ui.undo}</button></div>{/if}
{#if confirmBatch}<Sheet title={ui.batchTitle(confirmBatch.length)} close={()=>confirmBatch=null}><Button onclick={()=>{const items=confirmBatch!;confirmBatch=null;void add(items,batchCollection,true)}}>{ui.addItems}</Button><Button secondary onclick={()=>confirmBatch=null}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmSignout}<Sheet title={ui.signoutTitle} close={()=>confirmSignout=false}><p>{ui.signoutDetail}</p><Button onclick={()=>{confirmSignout=false;void signout()}}>{ui.signOut}</Button><Button secondary onclick={()=>confirmSignout=false}>{ui.cancel}</Button></Sheet>{/if}
{#if mergePrompt}<Sheet title={ui.mergeTitle(live.length)}><p>{ui.mergeHistoryDetail}</p><Button onclick={()=>void acceptMerge()}>{ui.mergeAdd}</Button><Button secondary onclick={()=>discardPrompt=true}>{ui.keepSeparate}</Button></Sheet>{/if}
{#if discardPrompt}<Sheet title={ui.discardTitle} close={()=>discardPrompt=false}><p>{ui.discardDetail}</p><Button onclick={()=>void discardLocal()}>{ui.discardLocal}</Button><Button secondary onclick={()=>discardPrompt=false}>{ui.cancel}</Button></Sheet>{/if}
</main>
